{
  "name": "magpie-muse-web",
  "version": "0.6.1",
  "description": "Magpie provider plugin for muse.ai: sign in to each account in a browser window, use Muse Spark with tool calls in Codex, OpenCode and other agents, and see each account's weekly usage",
  "type": "module",
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "engine/",
    "icon.svg",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test contract.test.mjs \"test/*.test.mjs\" connector/contract.test.mjs"
  },
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "muse",
    "muse-ai",
    "muse-spark"
  ],
  "author": "JohnWang (https://github.com/JohnWangggg)",
  "license": "MIT",
  "homepage": "https://github.com/JohnWangggg/magpie-muse-web#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JohnWangggg/magpie-muse-web.git"
  },
  "bugs": {
    "url": "https://github.com/JohnWangggg/magpie-muse-web/issues"
  },
  "engines": {
    "node": ">=20"
  },
  "os": [
    "darwin",
    "linux",
    "win32"
  ],
  "magpie": {
    "icon": "data:image/svg+xml;base64,",
    "maxConcurrency": 1
  },
  "publishConfig": {
    "access": "public"
  }
}

import { spawn } from "node:child_process"
import { existsSync, readFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { dataDir, enginePort } from "./engine/paths.mjs"
import { VERSION } from "./engine/version.mjs"

const PROVIDER = "muse-web"
const MODEL = "muse-spark"
const CONTROL_TIMEOUT_MS = 10_000
const ENGINE_START_MS = 20_000
// the engine's 15 minutes to sign in, then the test message it sends to the new account
const LOGIN_LIMIT_MS = 18 * 60_000
const REFRESH_LEAD_MS = 10 * 60_000
// muse.ai names no limits. These are what one web prompt comfortably holds, so clients
// compact long conversations before the page has to take them.
const CONTEXT_TOKENS = 128_000
const OUTPUT_TOKENS = 16_000
const HERE = path.dirname(fileURLToPath(import.meta.url))
const ENGINE_MAIN = path.join(HERE, "engine", "main.mjs")
const ICON = (() => {
  try {
    return `data:image/svg+xml;base64,${readFileSync(path.join(HERE, "icon.svg")).toString("base64")}`
  } catch {
    return ""
  }
})()

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

// An engine at least as new as this plugin is kept: a Magpie that has not reloaded the plugin
// yet must not keep replacing the engine a newer copy of the plugin started.
function current(version) {
  if (!version) return false
  const a = version.split(".").map(Number)
  const b = VERSION.split(".").map(Number)
  for (let i = 0; i < 3; i++) if ((a[i] || 0) !== (b[i] || 0)) return (a[i] || 0) > (b[i] || 0)
  return true
}

function originFrom(value) {
  return String(value).trim().replace(/\/+$/, "").replace(/\/v1$/, "")
}

function isOurs(input) {
  const id = input?.model?.providerID || input?.provider?.info?.id || input?.message?.model?.providerID || ""
  return id === PROVIDER || id === `${PROVIDER}-plugin`
}

function handleOf(auth) {
  const value = auth?.type === "api" ? auth.key : auth?.type === "oauth" ? auth.refresh || auth.access : ""
  return typeof value === "string" ? value.trim() : ""
}

function engineHeaders(key, handle) {
  const headers = {}
  if (handle) headers["x-muse-account"] = handle
  if (key) headers.authorization = `Bearer ${key}`
  return headers
}

function structured(windows) {
  if (!Array.isArray(windows)) return []
  // One malformed meter should not throw away the valid ones.
  return windows.filter((item) => {
    return item && typeof item.name === "string" && item.name.trim() !== "" && typeof item.used === "number" && item.used >= 0 && item.used <= 100
  })
}

export const MuseWebPlugin = async (_input, options) => {
  const opt = options && typeof options === "object" ? options : {}
  // An engine named in options or MUSE_WEB_ENGINE is run by someone else; otherwise the plugin runs its own.
  const external = () => Boolean(opt.engine || process.env.MUSE_WEB_ENGINE)
  const engineOrigin = () => originFrom(opt.engine || process.env.MUSE_WEB_ENGINE || `http://127.0.0.1:${enginePort()}`)
  const engineBaseURL = () => `${engineOrigin()}/v1`
  const engineKey = () => {
    const own = String(opt.key ?? process.env.MUSE_WEB_ENGINE_KEY ?? "").trim()
    if (own || external()) return own
    const file = path.join(dataDir(), "engine.key")
    return existsSync(file) ? readFileSync(file, "utf8").trim() : ""
  }

  // The running engine's version, or "" when nothing of ours answers.
  async function running() {
    try {
      const res = await fetch(`${engineOrigin()}/v1/health`, { signal: AbortSignal.timeout(1500) })
      const body = res.ok ? await res.json() : null
      return body?.engine === "muse-web" ? String(body.version || "?") : ""
    } catch {
      return ""
    }
  }

  async function retire() {
    await fetch(`${engineOrigin()}/v1/shutdown`, {
      method: "POST",
      headers: engineHeaders(engineKey(), ""),
      signal: AbortSignal.timeout(CONTROL_TIMEOUT_MS),
    }).catch(() => {})
    const end = Date.now() + 8000
    while (Date.now() < end && (await running())) await sleep(250)
  }

  let starting = null
  let checkedAt = 0
  // Makes sure the bundled engine answers, starting it with this runtime (Magpie's Bun) if needed.
  function ensureEngine({ force = false } = {}) {
    if (external()) return Promise.resolve(true)
    if (!force && Date.now() - checkedAt < 30_000) return Promise.resolve(true)
    starting ??= (async () => {
      const version = await running()
      if (current(version)) return true
      // An engine left from an older plugin version is replaced; same data dir, same accounts.
      if (version) await retire()
      const child = spawn(process.execPath, [ENGINE_MAIN], {
        detached: true,
        stdio: "ignore",
        windowsHide: true,
        env: { ...process.env, NODE_USE_ENV_PROXY: "1", MUSE_WEB_PARENT_PID: String(process.pid) },
      })
      child.on("error", () => {})
      child.unref()
      const end = Date.now() + ENGINE_START_MS
      while (Date.now() < end) {
        await sleep(300)
        if (current(await running())) return true
      }
      return false
    })().then((ok) => {
      if (ok) checkedAt = Date.now()
      starting = null
      return ok
    })
    return starting
  }

  // Returns null when the engine is down or silent, so callers never mistake that for a refused sign-in.
  async function control(pathname, method, handle) {
    if (!(await ensureEngine())) return null
    try {
      return await fetch(`${engineOrigin()}${pathname}`, {
        method,
        headers: engineHeaders(engineKey(), handle),
        signal: AbortSignal.timeout(CONTROL_TIMEOUT_MS),
      })
    } catch {
      checkedAt = 0
      return null
    }
  }

  async function browserLogin() {
    const res = await control("/v1/login", "POST", "")
    if (!res?.ok) throw new Error(res ? `muse-web 引擎没能开始登录（HTTP ${res.status}）` : "muse-web 引擎没有启动；日志在数据目录的 engine.log")
    const { id, url } = await res.json()
    return {
      url,
      instructions: "在弹出的浏览器窗口里登录 muse.ai。登录后窗口会自动关闭，引擎再发一条测试消息，账号能回答才算登录成功。",
      method: "auto",
      async callback() {
        const end = Date.now() + LOGIN_LIMIT_MS
        while (Date.now() < end) {
          await sleep(1500)
          const poll = await control(`/v1/login/${id}`, "GET", "")
          if (!poll) continue
          if (!poll.ok) return { type: "failed", error: `muse-web 登录状态读不到（HTTP ${poll.status}）` }
          const state = await poll.json()
          if (state.status === "done") {
            const expires = Number.isFinite(state.expires) ? state.expires : Date.now() + 86_400_000
            return {
              type: "success",
              refresh: state.handle,
              access: state.handle,
              expires,
              ...(state.label ? { accountId: state.label } : {}),
              ...(state.label?.includes("@") ? { email: state.label } : {}),
            }
          }
          if (state.status === "failed") return { type: "failed", error: `muse.ai 登录：${state.error || "没有完成"}` }
        }
        return { type: "failed", error: "muse.ai 登录：没有在时限内完成" }
      },
    }
  }

  // Start (and so pre-warm) the engine as soon as Magpie loads the plugin, not at the first message.
  if (!external()) ensureEngine().catch(() => {})

  return {
    config: async (cfg) => {
      cfg.provider ??= {}
      const was = cfg.provider[PROVIDER] ?? {}
      cfg.provider[PROVIDER] = {
        name: "Muse Web",
        npm: "@ai-sdk/openai-compatible",
        api: engineBaseURL(),
        ...was,
        models: {
          // Text in, text out through the web chat; images and files never reach the page.
          // Tools are told in the prompt and the model's <tool_call> tags come back as tool calls.
          [MODEL]: {
            name: "Muse Spark",
            reasoning: false,
            attachment: false,
            tool_call: true,
            modalities: { input: ["text"], output: ["text"] },
            limit: { context: CONTEXT_TOKENS, output: OUTPUT_TOKENS },
            cost: { input: 0, output: 0, cache_read: 0, cache_write: 0 },
          },
          ...(was.models ?? {}),
        },
      }
    },

    auth: {
      provider: PROVIDER,
      maxConcurrency: 1,
      ...(ICON ? { icon: ICON } : {}),
      // magpie renews the sign-in this long before it ends, through refresh() below
      refreshLead: REFRESH_LEAD_MS,
      methods: [
        { type: "oauth", label: "muse.ai（浏览器登录）", authorize: browserLogin },
        { type: "api", label: "引擎账号 ID（高级：配合自己运行的引擎）", placeholder: "muse-xxxxxxxxxxxx" },
      ],
      async refresh(auth) {
        const handle = handleOf(auth)
        if (!handle) throw Object.assign(new Error("muse-web account has no engine handle"), { signIn: "expired" })
        const res = await control("/v1/session/refresh", "POST", handle)
        if (!res) throw new Error("engine unreachable")
        if (res.status === 401) throw Object.assign(new Error("session refused"), { signIn: "expired" })
        if (!res.ok) throw new Error("session refresh unavailable")
        const body = await res.json()
        // muse.ai does not always expose a cookie expiry. Keep the account usable with the old
        // deadline when it is still in the future, otherwise give it a day and try again later.
        const expires = Number.isFinite(body.expires)
          ? body.expires
          : Number.isFinite(auth?.expires) && auth.expires > Date.now()
            ? auth.expires
            : Date.now() + 86_400_000
        return auth?.type === "oauth" ? { access: handle, refresh: handle, expires } : { expires }
      },
      async usage(getAuth) {
        const handle = handleOf(await getAuth())
        if (!handle) return { error: "muse-web account has no engine handle", signIn: "expired" }
        const res = await control("/v1/usage", "GET", handle)
        if (!res) return { error: "engine unreachable" }
        if (res.status === 401) return { error: "session refused", signIn: "expired" }
        let body = {}
        try {
          body = await res.json()
        } catch {
          body = {}
        }
        if (!res.ok) return { error: "usage unavailable" }
        const text = (v) => (typeof v === "string" && v.trim() ? v.trim() : "")
        const card = {
          ...(text(body.plan) ? { plan: text(body.plan) } : {}),
          ...(text(body.user) ? { user: text(body.user) } : {}),
          ...(text(body.until) ? { until: text(body.until) } : {}),
        }
        const windows = structured(body.windows)
        if (windows.length) return { ...card, windows, signIn: "kept" }
        // No quota to show is not an error when the engine described the account.
        if (card.plan) return { ...card, windows: [], signIn: "kept" }
        return { error: text(body.error) || "no structured quota" }
      },
      async loader(getAuth) {
        return {
          baseURL: engineBaseURL(),
          async fetch(input, init) {
            const auth = await getAuth()
            const handle = handleOf(auth)
            if (!handle) throw Object.assign(new Error("muse-web account has no engine handle"), { signIn: "expired" })
            const incoming = new Headers(init?.headers)
            const send = async () => {
              await ensureEngine()
              const headers = new Headers(engineHeaders(engineKey(), handle))
              for (const name of ["content-type", "accept", "x-muse-session"]) {
                const value = incoming.get(name)
                if (value) headers.set(name, value)
              }
              return fetch(input, { method: init?.method, headers, body: init?.body, signal: init?.signal })
            }
            let res
            try {
              res = await send()
            } catch (err) {
              // The engine may have been stopped or crashed since the last check; start it and try once more.
              if (external() || init?.signal?.aborted || !(await ensureEngine({ force: true }))) throw err
              res = await send()
            }
            const out = new Headers(res.headers)
            out.delete("content-length")
            if (res.status === 401) out.set("x-magpie-sign-in", "expired")
            else if (res.ok) out.set("x-magpie-sign-in", "kept")
            return new Response(res.body, { status: res.status, statusText: res.statusText, headers: out })
          },
        }
      },
    },

    "chat.headers": async (input, output) => {
      if (!isOurs(input)) return
      if (input.sessionID) output.headers["x-muse-session"] = input.sessionID
    },
  }
}

// Engine process. The plugin starts it detached with Magpie's own Bun; `node main.mjs` works too.
// Settings (all optional): MUSE_WEB_HOME, MUSE_WEB_ENGINE_PORT, MUSE_WEB_PROXY, MUSE_WEB_BROWSER
// (headless | hidden | show), MUSE_WEB_CHROME, MUSE_WEB_SITE, MUSE_WEB_IDLE_MIN.
// MUSE_WEB_PARENT_PID is set by the plugin: the engine stops when that process exits.
import { appendFileSync, mkdirSync, renameSync, statSync } from "node:fs"
import path from "node:path"
import { findBrowser } from "./browser.mjs"
import { Logins } from "./login.mjs"
import { AuthError, Muse, QuotaError, redact } from "./muse.mjs"
import { proxiedFetch, resolveProxy } from "./net.mjs"
import { watchParent } from "./parent.mjs"
import { dataDir, engineKey, enginePort } from "./paths.mjs"
import { createServer, VERSION } from "./server.mjs"
import { Store } from "./store.mjs"

const env = process.env
const dir = dataDir(env)
mkdirSync(dir, { recursive: true })
const logFile = path.join(dir, "engine.log")

function log(line) {
  process.stderr.write(line + "\n")
  try {
    if (statSync(logFile, { throwIfNoEntry: false })?.size > 5 << 20) renameSync(logFile, `${logFile}.1`)
    appendFileSync(logFile, line + "\n")
  } catch {}
}

const masked = (url) => String(url).replace(/\/\/[^@/]+@/, "//***@")
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

// A new account's VM can still be warming when the test message goes out. Retry that, but not
// a refused session (AuthError) or a spent allowance (QuotaError, still a working sign-in).
async function verifyAccount(account, tries = 3) {
  let last
  for (let i = 0; i < tries; i++) {
    try {
      return await muse.verify(account)
    } catch (err) {
      last = err
      if (err instanceof AuthError || err instanceof QuotaError) throw err
      if (i < tries - 1) await sleep(8_000 * (i + 1))
    }
  }
  throw last
}
const key = engineKey(dir)
const port = enginePort(env)
const site = (env.MUSE_WEB_SITE || "https://muse.ai").replace(/\/+$/, "")
const proxy = resolveProxy(env)
const fetchImpl = proxiedFetch(proxy)
const executable = findBrowser(env)
const mode = ["headless", "hidden", "show"].includes(env.MUSE_WEB_BROWSER) ? env.MUSE_WEB_BROWSER : "headless"
const idleMs = (Number(env.MUSE_WEB_IDLE_MIN) || 60) * 60_000
const prewarm = env.MUSE_WEB_PREWARM !== "0"
const verifyLogin = env.MUSE_WEB_VERIFY_LOGIN !== "0"

const store = new Store(path.join(dir, "accounts.json"))
const muse = new Muse({
  site,
  executable,
  profileDir: path.join(dir, "browser"),
  headless: mode === "headless",
  hidden: mode === "hidden",
  proxy,
  fetchImpl,
  onCookies: (id, cookies, exp, vm) => store.update(id, cookies, exp, vm),
  onLost: (why) => log(`${new Date().toTimeString().slice(0, 8)} browser lost (${why}) — a new one starts with the next request`),
})
const logins = new Logins({
  site,
  executable,
  dir: path.join(dir, "login"),
  proxy,
  fetchImpl,
  headless: env.MUSE_WEB_LOGIN_HEADLESS === "1", // tests only: a person has to see the sign-in window
  onDone: async (c, e, label, vm) => {
    const saved = store.add(c, e, label, vm)
    // the account's context still holds the cookies of before
    if (saved.again) await muse.closeAccount(saved.handle).catch(() => {})
    woken.set(saved.handle, Date.now())
    if (verifyLogin) {
      const t0 = Date.now()
      const at = new Date().toTimeString().slice(0, 8)
      try {
        await verifyAccount(store.get(saved.handle))
        log(`${at} verify account=${saved.handle} ${Date.now() - t0}ms`)
      } catch (err) {
        log(`${at} verify account=${saved.handle} failed reason=${redact(err.message)}`)
        // a used-up account is still a working sign-in
        if (!(err instanceof QuotaError)) {
          if (!saved.again) {
            await muse.closeAccount(saved.handle).catch(() => {})
            store.remove(saved.handle)
          }
          throw new Error(`已登录，但账号没有回答测试消息：${err.message}`)
        }
      }
    }
    if (prewarm) warm([saved.handle])
    return saved
  },
})

// All accounts at once: each page spends its ~10 s waiting on its own VM, not on this machine,
// and Magpie may send the first message to any of them. Usage is read after, one at a time.
async function warm(handles) {
  const ready = await Promise.all(handles.map(async (handle) => {
    const account = store.get(handle)
    if (!account) return null
    const t0 = Date.now()
    try {
      await muse.warm(account)
      log(`${new Date().toTimeString().slice(0, 8)} warm account=${handle} ${Date.now() - t0}ms`)
      return account
    } catch (err) {
      log(`${new Date().toTimeString().slice(0, 8)} warm account=${handle} failed reason=${redact(err.message)}`)
      return null
    }
  }))
  for (const account of ready) if (account) await readUsage(account)
}

async function readUsage(account, maxAgeMs = 0) {
  const t0 = Date.now()
  const at = () => new Date().toTimeString().slice(0, 8)
  try {
    const u = await muse.readUsage(account, { maxAgeMs })
    if (u && u.at >= t0) log(`${at()} usage account=${account.id} ${Date.now() - t0}ms ${u.windows.map((w) => `${w.name}=${w.used}%`).join(" ")}`)
  } catch (err) {
    log(`${at()} usage account=${account.id} failed reason=${redact(err.message)}`)
  }
}

let lastUse = Date.now()
const server = createServer({
  muse,
  logins,
  store,
  key,
  port,
  site,
  log,
  onActivity: () => { lastUse = Date.now() },
  readUsage,
  onShutdown: () => shutdown("asked to stop"),
})

// Keep-alive as muse2api 1.6.1 has it: not a heartbeat, but a renewal and VM wake for an
// account nobody has woken for 6 hours. It is not use: the idle clock below doesn't move.
const KEEPALIVE_EVERY_MS = 6 * 3600_000
const woken = new Map(store.handles().map((h) => [h, Date.now()]))
setInterval(async () => {
  for (const handle of store.handles()) {
    const account = store.get(handle)
    if (!account || Date.now() - (woken.get(handle) || 0) < KEEPALIVE_EVERY_MS) continue
    woken.set(handle, Date.now())
    const at = new Date().toTimeString().slice(0, 8)
    try {
      const { vmState } = await muse.keepAlive(account)
      log(`${at} keepalive account=${handle} vm=${vmState || "?"}`)
    } catch (err) {
      log(`${at} keepalive account=${handle} failed reason=${redact(err.message)}`)
    }
  }
}, 30 * 60_000).unref()

// The browser is the heavy part; let it go when nobody has used the engine for a while.
setInterval(() => {
  if (muse.started && Date.now() - lastUse > idleMs) {
    log(`${new Date().toTimeString().slice(0, 8)} idle — browser closed until the next request`)
    muse.stop()
  }
}, 60_000).unref()

server.on("error", async (err) => {
  if (err.code === "EADDRINUSE") {
    const other = await fetch(`http://127.0.0.1:${port}/v1/health`).then((r) => r.json()).catch(() => null)
    if (other?.engine === "muse-web") {
      log(`another muse-web engine already serves port ${port}; leaving it running`)
      process.exit(0)
    }
    log(`port ${port} is taken by something else; set MUSE_WEB_ENGINE_PORT`)
    process.exit(1)
  }
  log(`engine error: ${err.message}`)
  process.exit(1)
})

server.listen(port, "127.0.0.1", () => {
  log(
    `muse-web engine ${VERSION} listening on http://127.0.0.1:${port} · ${store.count()} accounts · ` +
      `browser ${executable ? `${path.basename(executable)} (${mode})` : "not found"} · proxy ${masked(proxy)} · data ${dir}`,
  )
  if (prewarm && executable) warm(store.handles())
})

async function shutdown(why) {
  log(`${new Date().toTimeString().slice(0, 8)} engine stopping (${why})`)
  logins.stopAll()
  await muse.stop().catch(() => {})
  process.exit(0)
}

for (const sig of ["SIGINT", "SIGTERM"]) process.on(sig, () => shutdown(sig))

// Detached so a plugin reload or replacement does not kill it; this stops it when Magpie itself goes.
watchParent(env.MUSE_WEB_PARENT_PID, () => shutdown("Magpie exited"))

// Loopback HTTP surface of the engine. Same contract as the Python engine:
// chat SSE · 401 sign-in expired · 429 account busy · 503 engine trouble.
import http from "node:http"
import { randomUUID, timingSafeEqual } from "node:crypto"
import { AuthError, expiryMs, PromptTooLongError, QuotaError, redact, renewSession } from "./muse.mjs"
import { buildPrompt, PromptError } from "./prompt.mjs"
import { functions, parseToolCalls, stripLabels, TOOLS_REMINDER, toolChoiceRequired, toolsPrompt } from "./tools.mjs"

import { VERSION } from "./version.mjs"

export { VERSION }
const MODEL = "muse-spark"
const USAGE_STALE_MS = 30 * 60_000
const USAGE_AFTER_CHAT_MS = 2 * 60_000

class HttpError extends Error {
  constructor(status, message, code = "", retryAfter = 0) {
    super(message)
    this.status = status
    this.code = code
    this.retryAfter = retryAfter
  }
}

function same(a, b) {
  const x = Buffer.from(String(a))
  const y = Buffer.from(String(b))
  return x.length === y.length && timingSafeEqual(x, y)
}

function json(res, status, body) {
  const data = JSON.stringify(body)
  res.writeHead(status, { "content-type": "application/json; charset=utf-8", "content-length": Buffer.byteLength(data) })
  res.end(data)
}

function fail(res, status, message, { code = "", retryAfter = 0 } = {}) {
  const type = status === 401 ? "authentication_error"
    : status === 429 ? "rate_limit_error"
    : status >= 400 && status < 500 ? "invalid_request_error"
    : "engine_error"
  const data = JSON.stringify({ error: { message: redact(message), type, ...(code ? { code } : {}) } })
  const headers = { "content-type": "application/json; charset=utf-8", "content-length": Buffer.byteLength(data) }
  if (retryAfter > 0) headers["retry-after"] = String(Math.max(1, Math.ceil(retryAfter)))
  res.writeHead(status, headers)
  res.end(data)
}

// A GenerationError's message is the only thing the page gave us; turn it into a code the
// gateway and the agent can act on (retry now, wait for the VM, or re-sign-in).
function generationCode(err) {
  const text = String(err?.message || "")
  if (/预热|warming/i.test(text)) return ["vm_warming", 10]
  if (/页面|page|加载/i.test(text)) return ["page_unavailable", 10]
  if (/超时|timeout/i.test(text)) return ["upstream_timeout", 5]
  if (/没有发出去|send/i.test(text)) return ["send_failed", 2]
  return ["engine_unavailable", 5]
}

async function body(req, limit = 8 << 20) {
  const chunks = []
  let size = 0
  for await (const chunk of req) {
    size += chunk.length
    if (size > limit) throw new HttpError(413, "request too large", "request_too_large")
    chunks.push(chunk)
  }
  if (!size) return {}
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8"))
  } catch {
    throw new HttpError(400, "invalid JSON body", "invalid_json")
  }
}

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c])

function loginPage(state) {
  const done = state?.status === "done"
  const failed = state?.status === "failed" || !state
  const title = done ? "登录完成" : failed ? "登录没有完成" : "请到另一个浏览器窗口登录 muse.ai"
  const note = done
    ? "可以关掉这个页面，回到 Magpie。"
    : failed
      ? esc(state?.error || "找不到这次登录，请回到 Magpie 重新发起。")
      : `这个页面只显示进度，这里不能登录。请在引擎另外打开的 Chrome、Edge、Chromium 或 Brave 窗口里完成登录。${esc(state.step || "")}${state.note ? `（上一次出错：${esc(state.note)}）` : ""}。登录成功后那个窗口会自动关闭，这个页面也会更新。`
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>muse-web 登录</title>
${done || failed ? "" : '<meta http-equiv="refresh" content="2">'}
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
:root{color-scheme:light dark;font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}
body{margin:0;min-height:100vh;display:grid;place-items:center;background:Canvas;color:CanvasText}
main{max-width:30rem;padding:2rem}
h1{font-size:1.25rem;margin:0 0 .5rem;font-weight:600}
p{margin:0;opacity:.75}
.dot{display:inline-block;width:.6rem;height:.6rem;border-radius:50%;margin-right:.5rem;vertical-align:middle;background:${done ? "#2f9e44" : failed ? "#e03131" : "#f59f00"}}
</style></head><body><main><h1><span class="dot"></span>${title}</h1><p>${note}</p></main></body></html>`
}

export function createServer({ muse, logins, store, key, port = 18611, log = () => {}, onActivity = () => {}, onShutdown = () => {}, readUsage = (a, maxAgeMs) => muse.readUsage(a, { maxAgeMs }).catch(() => null), site = muse?.site }) {
  const busy = new Set()

  function authorize(req) {
    const header = String(req.headers.authorization || "")
    const token = header.startsWith("Bearer ") ? header.slice(7).trim() : ""
    if (!token || !same(token, key)) throw new HttpError(401, "bad engine key", "engine_key_invalid")
  }

  function account(req) {
    const id = String(req.headers["x-muse-account"] || "").trim()
    if (!id) throw new HttpError(400, "missing X-Muse-Account", "account_missing")
    const item = store.get(id)
    if (!item) throw new HttpError(401, "unknown account; sign in again", "account_unknown")
    return item
  }

  async function chat(req, res, meta) {
    const payload = await body(req)
    const acct = account(req)
    meta.account = acct.id
    let prompt
    try {
      prompt = buildPrompt(payload.messages)
    } catch (err) {
      if (err instanceof PromptError) throw new HttpError(400, err.message, "invalid_request")
      throw err
    }
    const toolNote = toolsPrompt(payload.tools, payload.tool_choice)
    const requiredTool = toolChoiceRequired(payload.tools, payload.tool_choice)
    if (toolNote) prompt = { ...prompt, full: `${prompt.full}\n\n${toolNote}`, last: prompt.last && `${prompt.last}\n\n${TOOLS_REMINDER}` }
    if (busy.has(acct.id)) throw new HttpError(429, "account busy", "account_busy", 1)
    busy.add(acct.id)
    const session = String(req.headers["x-muse-session"] || "").trim()
    meta.session = session
    // Each conversation has its own tab; the engine knows whether that tab already holds it.
    const continuing = !!(session && prompt.turns > 1)
    const timing = {}
    const stream = payload.stream !== false
    const id = `chatcmpl-${randomUUID()}`
    const created = Math.floor(Date.now() / 1000)
    const ac = new AbortController()
    res.on("close", () => { if (!res.writableFinished) ac.abort() })
    let started = false
    let text = ""
    const chunk = (delta, finish = null) =>
      `data: ${JSON.stringify({ id, object: "chat.completion.chunk", created, model: MODEL, choices: [{ index: 0, delta, finish_reason: finish }] })}\n\n`
    const begin = () => {
      if (started) return
      res.writeHead(200, { "content-type": "text/event-stream; charset=utf-8", "cache-control": "no-cache", connection: "keep-alive" })
      res.write(chunk({ role: "assistant", content: "" }))
      started = true
    }
    // With tools, text goes out a whole line at a time, code block labels left out, and from the
    // first "<", "{" or "`" on it is held back: that may open a tool call.
    let shown = ""
    // A required tool must be parsed before any text goes out; otherwise the client would see a
    // normal answer and never learn that the tool was expected.
    let holding = !!requiredTool
    let pending = ""
    try {
      for await (const delta of muse.chat(acct, prompt, { conversation: session, continuing, signal: ac.signal, timing, expectTools: !!toolNote })) {
        text += delta
        if (!stream || holding) continue
        let piece = delta
        if (toolNote) {
          pending += delta
          const at = pending.search(/[<{`]/)
          if (at !== -1) {
            piece = pending.slice(0, at)
            holding = true
          } else {
            const nl = pending.lastIndexOf("\n")
            if (nl === -1) continue
            piece = pending.slice(0, nl + 1)
            pending = pending.slice(nl + 1)
          }
          piece = stripLabels(piece)
        }
        if (!piece) continue
        begin()
        res.write(chunk({ content: piece }))
        shown += piece
      }
      let whole = timing.text || text
      let parsed = toolNote ? parseToolCalls(whole, payload.tools) : { calls: [], content: whole }
      let calls = parsed.calls
      let content = parsed.content
      const satisfied = () => requiredTool === "required"
        ? calls.length > 0
        : !requiredTool || calls.some((c) => c.name === requiredTool)
      if (requiredTool && !satisfied() && session) {
        // One repair turn: the model answered with prose although the client required a tool.
        const repair = "你刚才没有按格式调用工具。请只输出一个 tool_call 代码块，里面是一个 JSON 对象：{\"name\": \"工具名\", \"arguments\": {参数}}。不要输出其他文字。"
        let repaired = ""
        try {
          for await (const delta of muse.chat(acct, { full: repair, last: repair, turns: 1 }, { conversation: session, continuing: true, signal: ac.signal, timing: {}, expectTools: true })) repaired += delta
          const again = parseToolCalls(repaired, payload.tools)
          if (again.calls.length) {
            calls = again.calls
            content = again.content
            whole = repaired
            text = repaired
          }
        } catch (err) {
          if (err instanceof AuthError || err instanceof QuotaError) throw err
          // Keep the first answer; the 422 below still tells the client the contract was missed.
        }
      }
      if (requiredTool && !satisfied()) {
        throw new HttpError(422, "model did not call the required tool", "tool_call_not_parsed")
      }
      const toolCalls = calls.map((c) => ({ id: `call_${randomUUID().replaceAll("-", "").slice(0, 24)}`, type: "function", function: c }))
      const finish = toolCalls.length ? "tool_calls" : "stop"
      if (toolNote) meta.tools = `${functions(payload.tools).length}→${toolCalls.map((c) => c.function.name).join(",") || "text"}`
      if (!stream) {
        const message = { role: "assistant", content: toolCalls.length ? content || null : whole }
        if (toolCalls.length) message.tool_calls = toolCalls
        json(res, 200, { id, object: "chat.completion", created, model: MODEL, choices: [{ index: 0, message, finish_reason: finish }] })
        return
      }
      begin()
      // what is left of the text: past what streamed, when the final text still begins with it
      const rest = toolNote ? stripLabels(toolCalls.length ? content : whole) : whole
      const more = rest.startsWith(shown) ? rest.slice(shown.length) : ""
      if (more) res.write(chunk({ content: more }))
      toolCalls.forEach((c, index) => {
        res.write(chunk({ tool_calls: [{ index, id: c.id, type: "function", function: { name: c.function.name, arguments: "" } }] }))
        res.write(chunk({ tool_calls: [{ index, function: { arguments: c.function.arguments } }] }))
      })
      res.write(chunk({}, finish))
      res.end("data: [DONE]\n\n")
    } catch (err) {
      if (err instanceof HttpError) throw err
      await muse.closeTab(acct.id, session).catch(() => {})
      if (err instanceof AuthError) throw new HttpError(401, err.message, "session_expired")
      if (err instanceof QuotaError) {
        setTimeout(() => readUsage(acct, 0), 1500).unref?.()
        throw new HttpError(429, err.message, "quota_spent", 60)
      }
      if (err instanceof PromptTooLongError) throw new HttpError(413, err.message, "prompt_too_long")
      if (!started) {
        const [code, retryAfter] = generationCode(err)
        throw new HttpError(503, err.message || "engine unavailable", code, retryAfter)
      }
      meta.reason = redact(err.message)
      if (!res.writableEnded && !res.destroyed) {
        res.write(`data: ${JSON.stringify({ error: { message: redact(err.message), type: "engine_error", code: "stream_interrupted" } })}\n\n`)
        res.end("data: [DONE]\n\n")
      }
    } finally {
      busy.delete(acct.id)
      // what the answer spent shows on the card soon after, read at most every 2 minutes
      if (!ac.signal.aborted) setTimeout(() => readUsage(acct, USAGE_AFTER_CHAT_MS), 1500).unref?.()
      meta.timing = [
        timing.how && `tab=${timing.how}`,
        timing.sent && `sent=${timing.sent}`,
        timing.tabMs != null && `page=${timing.tabMs}ms`,
        timing.firstMs != null && `first=${timing.firstMs}ms`,
      ].filter(Boolean).join(" ")
    }
  }

  async function refresh(req, res, meta) {
    const acct = account(req)
    meta.account = acct.id
    try {
      const renewed = await renewSession(site, acct.cookies, acct.cookies_exp, { fetchImpl: muse.fetchImpl, wakeVm: false })
      store.update(acct.id, renewed.cookies, renewed.cookies_exp)
      json(res, 200, { expires: expiryMs(renewed.cookies_exp) })
    } catch (err) {
      if (err instanceof AuthError) throw new HttpError(401, err.message, "session_expired")
      const [code, retryAfter] = generationCode(err)
      throw new HttpError(503, err.message, code, retryAfter)
    }
  }

  const routes = {
    "GET /v1/health": (req, res) => json(res, 200, { ok: true, engine: "muse-web", version: VERSION, accounts: store.count() }),
    "GET /v1/models": (req, res) => {
      authorize(req)
      json(res, 200, { object: "list", data: [{ id: MODEL, object: "model", owned_by: "muse.ai" }] })
    },
    // Account handles only: a connector edition needs to let the user pick one without reading
    // the engine's accounts.json or any cookie.
    "GET /v1/accounts": (req, res) => {
      authorize(req)
      const accounts = store.handles().map((id) => {
        const account = store.get(id)
        return { id, label: account.label || "", expires: expiryMs(account.cookies_exp) }
      })
      json(res, 200, { accounts })
    },
    "POST /v1/chat/completions": async (req, res, meta) => {
      authorize(req)
      await chat(req, res, meta)
    },
    "POST /v1/session/refresh": async (req, res, meta) => {
      authorize(req)
      await refresh(req, res, meta)
    },
    // The account's meters as muse.ai's settings page shows them, read in its browser context;
    // the plan line also says whether the next message is quick (page ready) or has to wake it.
    // A reading older than USAGE_STALE_MS is renewed: waited for when there is none yet.
    "GET /v1/usage": async (req, res, meta) => {
      authorize(req)
      const acct = account(req)
      meta.account = acct.id
      let u = muse.usageOf(acct.id)
      const { ready } = muse.state(acct.id)
      if (ready && !busy.has(acct.id) && (!u || Date.now() - u.at > USAGE_STALE_MS)) {
        const reading = readUsage(acct, USAGE_STALE_MS)
        // under the plugin's 10 s for an engine call; a slower reading shows on the next ask
        if (!u) u = await Promise.race([reading, new Promise((r) => setTimeout(r, 8000))]) || muse.usageOf(acct.id)
      }
      const status = busy.has(acct.id) ? "正在回答" : ready ? "已就绪" : "闲置，下一条约需 30 秒唤醒"
      const expires = expiryMs(acct.cookies_exp)
      json(res, 200, {
        plan: `${u?.plan || "muse.ai"} · ${status}`,
        windows: u?.windows || [],
        ...(acct.label ? { user: acct.label } : {}),
        ...(expires ? { until: new Date(expires).toISOString() } : {}),
      })
    },
    "POST /v1/shutdown": (req, res) => {
      authorize(req)
      json(res, 200, { ok: true })
      res.once("finish", () => onShutdown())
    },
    "POST /v1/login": async (req, res) => {
      authorize(req)
      const id = await logins.start()
      json(res, 200, { id, url: `http://127.0.0.1:${port}/login/${id}` })
    },
  }

  const server = http.createServer(async (req, res) => {
    const t0 = Date.now()
    onActivity()
    const url = new URL(req.url, "http://127.0.0.1")
    const meta = { account: "", session: "", reason: "", timing: "" }
    try {
      const route = routes[`${req.method} ${url.pathname}`]
      let m
      if (route) await route(req, res, meta)
      else if (req.method === "GET" && (m = url.pathname.match(/^\/v1\/login\/([\w-]+)$/))) {
        authorize(req)
        const state = logins.status(m[1])
        if (!state) throw new HttpError(404, "no such login", "login_not_found")
        json(res, 200, state)
      } else if (req.method === "GET" && (m = url.pathname.match(/^\/login\/([\w-]+)$/))) {
        const html = loginPage(logins.status(m[1]))
        res.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" })
        res.end(html)
      } else throw new HttpError(404, "not found", "not_found")
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500
      meta.reason = redact(err.message)
      if (!res.headersSent) fail(res, status, err.message, {
        code: err instanceof HttpError ? err.code : "",
        retryAfter: err instanceof HttpError ? err.retryAfter : 0,
      })
      else if (!res.writableEnded) res.end()
    } finally {
      onActivity()
      const at = new Date().toTimeString().slice(0, 8)
      const who = meta.account ? ` account=${meta.account}` : ""
      const ses = meta.session ? ` session=${meta.session.slice(0, 12)}` : ""
      log(`${at} ${res.statusCode} ${req.method} ${url.pathname}${who}${ses} ${Date.now() - t0}ms${meta.timing ? ` ${meta.timing}` : ""}${meta.tools ? ` tools=${meta.tools}` : ""}${meta.reason ? ` reason=${meta.reason}` : ""}`)
    }
  })
  server.requestTimeout = 0
  server.headersTimeout = 30_000
  return server
}
